32: type namespaceManager struct {
33: 	mu         sync.Mutex
34: 	namespaces map[string]*observerpb.Namespace
35: }
36: 
37: // NewNamespaceManager creates a namespace manager.
38: func NewNamespaceManager() *namespaceManager {
39: 	return &namespaceManager{
40: 		namespaces: make(map[string]*observerpb.Namespace),
41: 	}
42: }
43: 
44: // AddNamespace adds ns to the namespace manager.
45: func (m *namespaceManager) AddNamespace(ns *observerpb.Namespace) {
46: 	m.mu.Lock()
47: 	defer m.mu.Unlock()
48: 
49: 	key := ns.GetCluster() + "/" + ns.GetNamespace()
50: 	m.namespaces[key] = ns
51: }
52: 
53: // GetNamespaces returns all namespaces sorted by cluster and namespace.
54: func (m *namespaceManager) GetNamespaces() []*observerpb.Namespace {
55: 	m.mu.Lock()
56: 	defer m.mu.Unlock()
57: 
58: 	namespaces := make([]*observerpb.Namespace, 0, len(m.namespaces))
59: 	for _, ns := range m.namespaces {
60: 		namespaces = append(namespaces, ns)
61: 	}
62: 	slices.SortFunc(namespaces, func(a, b *observerpb.Namespace) bool {
63: 		if a.Cluster != b.Cluster {
64: 			return a.Cluster < b.Cluster
65: 		}
66: 		return a.Namespace < b.Namespace
67: 	})
68: 
69: 	return namespaces
70: }
