113: // GetFlows implements observerpb.ObserverServer.GetFlows by proxying requests to
114: // the hubble instance the proxy is connected to.
115: func (s *Server) GetFlows(req *observerpb.GetFlowsRequest, stream observerpb.Observer_GetFlowsServer) error {
116: 	ctx := stream.Context()
117: 	md, ok := metadata.FromIncomingContext(ctx)
118: 	if ok {
119: 		ctx = metadata.NewOutgoingContext(ctx, md)
120: 	}
121: 	ctx, cancel := context.WithCancel(ctx)
122: 
123: 	defer cancel()
124: 
125: 	peers := s.peers.List()
126: 	qlen := s.opts.sortBufferMaxLen // we don't want to buffer too many flows
127: 	if nqlen := req.GetNumber() * uint64(len(peers)); nqlen > 0 && nqlen < uint64(qlen) {
128: 		// don't make the queue bigger than necessary as it would be a problem
129: 		// with the priority queue (we pop out when the queue is full)
130: 		qlen = int(nqlen)
131: 	}
132: 
133: 	g, gctx := errgroup.WithContext(ctx)
134: 	flows := make(chan *observerpb.GetFlowsResponse, qlen)
135: 	var connectedNodes, unavailableNodes []string
136: 
137: 	for _, p := range peers {
138: 		if !isAvailable(p.Conn) {
139: 			s.opts.log.WithField("address", p.Address).Infof(
140: 				"No connection to peer %s, skipping", p.Name,
141: 			)
142: 			s.peers.ReportOffline(p.Name)
143: 			unavailableNodes = append(unavailableNodes, p.Name)
144: 			continue
145: 		}
146: 		connectedNodes = append(connectedNodes, p.Name)
147: 		p := p
148: 		g.Go(func() error {
149: 			// retrieveFlowsFromPeer returns blocks until the peer finishes
150: 			// the request by closing the connection, an error occurs,
151: 			// or gctx expires.
152: 			err := retrieveFlowsFromPeer(gctx, s.opts.ocb.observerClient(&p), req, flows)
153: 			if err != nil {
154: 				s.opts.log.WithFields(logrus.Fields{
155: 					"error": err,
156: 					"peer":  p,
157: 				}).Warning("Failed to retrieve flows from peer")
158: 				select {
159: 				case flows <- nodeStatusError(err, p.Name):
160: 				case <-gctx.Done():
161: 				}
162: 			}
163: 			return nil
164: 		})
165: 	}
166: 	go func() {
167: 		g.Wait()
168: 		close(flows)
169: 	}()
170: 
171: 	aggregated := aggregateErrors(ctx, flows, s.opts.errorAggregationWindow)
172: 	sortedFlows := sortFlows(ctx, aggregated, qlen, s.opts.sortBufferDrainTimeout)
173: 
174: 	// inform the client about the nodes from which we expect to receive flows first
175: 	if len(connectedNodes) > 0 {
176: 		status := nodeStatusEvent(relaypb.NodeState_NODE_CONNECTED, connectedNodes...)
177: 		if err := stream.Send(status); err != nil {
178: 			return err
179: 		}
180: 	}
181: 	if len(unavailableNodes) > 0 {
182: 		status := nodeStatusEvent(relaypb.NodeState_NODE_UNAVAILABLE, unavailableNodes...)
183: 		if err := stream.Send(status); err != nil {
184: 			return err
185: 		}
186: 	}
187: 
188: sortedFlowsLoop:
189: 	for {
190: 		select {
191: 		case flow, ok := <-sortedFlows:
192: 			if !ok {
193: 				break sortedFlowsLoop
194: 			}
195: 			if err := stream.Send(flow); err != nil {
196: 				return err
197: 			}
198: 		case <-ctx.Done():
199: 			break sortedFlowsLoop
200: 		}
201: 	}
202: 	return g.Wait()
203: }
