217: // GetNodes implements observerpb.ObserverClient.GetNodes.
218: func (s *Server) GetNodes(ctx context.Context, req *observerpb.GetNodesRequest) (*observerpb.GetNodesResponse, error) {
219: 	if md, ok := metadata.FromIncomingContext(ctx); ok {
220: 		ctx = metadata.NewOutgoingContext(ctx, md)
221: 	}
222: 	ctx, cancel := context.WithCancel(ctx)
223: 	defer cancel()
224: 	g, ctx := errgroup.WithContext(ctx)
225: 
226: 	peers := s.peers.List()
227: 	nodes := make([]*observerpb.Node, 0, len(peers))
228: 	for _, p := range peers {
229: 		n := &observerpb.Node{
230: 			Name: p.Name,
231: 			Tls: &observerpb.TLS{
232: 				Enabled:    p.TLSEnabled,
233: 				ServerName: p.TLSServerName,
234: 			},
235: 		}
236: 		if p.Address != nil {
237: 			n.Address = p.Address.String()
238: 		}
239: 		nodes = append(nodes, n)
240: 		if !isAvailable(p.Conn) {
241: 			n.State = relaypb.NodeState_NODE_UNAVAILABLE
242: 			s.opts.log.WithField("address", p.Address).Infof(
243: 				"No connection to peer %s, skipping", p.Name,
244: 			)
245: 			s.peers.ReportOffline(p.Name)
246: 			continue
247: 		}
248: 		n.State = relaypb.NodeState_NODE_CONNECTED
249: 		p := p
250: 		g.Go(func() error {
251: 			n := n
252: 			client := s.opts.ocb.observerClient(&p)
253: 			status, err := client.ServerStatus(ctx, &observerpb.ServerStatusRequest{})
254: 			if err != nil {
255: 				n.State = relaypb.NodeState_NODE_ERROR
256: 				s.opts.log.WithFields(logrus.Fields{
257: 					"error": err,
258: 					"peer":  p,
259: 				}).Warning("Failed to retrieve server status")
260: 				return nil
261: 			}
262: 			n.Version = status.GetVersion()
263: 			n.UptimeNs = status.GetUptimeNs()
264: 			n.MaxFlows = status.GetMaxFlows()
265: 			n.NumFlows = status.GetNumFlows()
266: 			n.SeenFlows = status.GetSeenFlows()
267: 			return nil
268: 		})
269: 	}
270: 	if err := g.Wait(); err != nil {
271: 		return nil, err
272: 	}
273: 	return &observerpb.GetNodesResponse{Nodes: nodes}, nil
274: }
