355: 			if len(unavailableNodes) < numUnavailableNodesReportMax {
356: 				unavailableNodes = append(unavailableNodes, p.Name)
357: 			}
358: 			continue
359: 		}
360: 		numConnectedNodes++
361: 		p := p
362: 		g.Go(func() error {
363: 			client := s.opts.ocb.observerClient(&p)
364: 			status, err := client.ServerStatus(ctx, req)
365: 			if err != nil {
366: 				s.opts.log.WithFields(logrus.Fields{
367: 					"error": err,
368: 					"peer":  p,
369: 				}).Warning("Failed to retrieve server status")
370: 				return nil
371: 			}
372: 			select {
373: 			case statuses <- status:
374: 			case <-ctx.Done():
375: 			}
376: 			return nil
377: 		})
378: 	}
379: 	go func() {
380: 		g.Wait()
381: 		close(statuses)
382: 	}()
383: 	resp := &observerpb.ServerStatusResponse{
384: 		Version: build.RelayVersion.String(),
